    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long a, b;
    cin >> a >> b;

    const long long INF = LLONG_MAX;
    const long long sum = a + b;
    long long ans = INF;
    long long mx1 = INF, mx2 = INF;

    for (long long i = 1; i <= sum / i; ++i) {
        if (i <= a / i && a % i == 0)
            mx1 = min(mx1, a / i);
        if (i <= b / i && b % i == 0)
            mx2 = min(mx2, b / i);

        if (sum % i == 0 && (mx1 <= sum / i || mx2 <= sum / i))
            ans = min(ans, 2 * i + 2 * (sum / i));
    }

    cout << ans;
    return 0;
}

